$(document).ready(()=>{xdesktop.afterReady()});let xdesktopResizeScheduled=!1;$(window).resize(()=>{if(xdesktopResizeScheduled)return;xdesktopResizeScheduled=!0,requestAnimationFrame(()=>{xdesktopResizeScheduled=!1,xdesktop.windowResize()})});const xdesktop=new function(){this.afterReady=()=>{if(setTimeout(()=>{xdesktop.windowResize()},0),$(".compact-message-list #listoptions fieldset").length&&$("#listoptions fieldset:first").remove(),$("body.skin-icloud.login-page").length&&!$("body.xbackground-login-image").length){const e=$("<div/>").addClass("icl-icons");let t=0;const n=()=>{t++,t>=13&&setTimeout(function(){e.fadeIn(800)},500)};for(let t=1;t<=13;t++){const s=$("<img/>").addClass("icl-icon-"+t).attr("alt","").on("load error",n);e.append(s),s.attr("src","skins/icloud/assets/images/icon-"+t+".png"),s[0].complete&&n()}$("body").append(e)}},this.windowResize=()=>{const e=$(".toolbar");if(!e.length)return;const t=e.offset().left+e.outerWidth()+5;[$("#searchfilter"),$("#quicksearchbar")].forEach(e=>{e.length&&e.css("visibility",e.offset().left<t?"hidden":"visible")})}}